    }

    public int getPort() {
        return port;
    }

    public String getCommand() {
        return command;
    }

    public String getBatchFile() {
        return batchFile;
    }

    public int getExecutionTimeout() {
        return executionTimeout;
    }

    public Integer getWidth() {
        return width;
    }

    public Integer getheight() {
        return height;
    }

    public boolean isQuiet() {
        return quiet;
    }

    public boolean isHelp() {
        return help;
    }

}

